# -*- coding: utf-8 -*-
"""Stage 5 — SQLite -> Postgres data copier.

Runs anywhere the SQLite file (DATA_DIR/quizpro.db) and a target DATABASE_URL are
both reachable (designed for Railway). It does NOT decide cutover — it only copies.

    DATABASE_URL=postgres://...  python migrate_sqlite_to_pg.py [--init] [--yes]

  --init   create the target schema first (db.init_db + analytics + billing inits)
  --yes    skip the confirmation prompt

What it does:
  * copies every user table in FK-safe (parent-first) topological order
  * preserves primary-key ids (IDENTITY columns are GENERATED BY DEFAULT)
  * handles self-referential FKs (categories.parent_id, refresh_tokens.replaced_by)
    with a null-then-update two-pass so row order never violates the constraint
  * reseeds IDENTITY sequences so future inserts don't collide
  * prints a verification report and validates row counts (exit 1 on any mismatch)

The copy core (`run_copy`) is DB-API agnostic and is exercised SQLite->SQLite by
test_migrate_copier.py; main() wires SQLite (source) -> psycopg (target).
"""
import os
import sys
import sqlite3

import db  # for DB_PATH + (optionally) schema init


# id-autoincrement tables get their identity sequence reseeded after copy.
def _id_tables():
    import re
    src = ""
    for f in ("db.py", "analytics.py", "billing.py"):
        try:
            src += open(f, encoding="utf-8").read()
        except OSError:
            pass
    out = set()
    for m in re.finditer(r"CREATE TABLE IF NOT EXISTS (\w+)\s*\((.*?)\n\s*\)", src, re.S):
        if re.search(r"\bid\s+INTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT", m.group(2), re.I):
            out.add(m.group(1).lower())
    return out


def discover(src):
    """Return (tables, columns, fkdeps, selfcols) read from the SQLite source."""
    cur = src.execute(
        "SELECT name FROM sqlite_master WHERE type='table' "
        "AND name NOT LIKE 'sqlite_%' ORDER BY name")
    tables = [r[0] for r in cur.fetchall()]
    columns, fkdeps, selfcols = {}, {}, {}
    for t in tables:
        columns[t] = [r[1] for r in src.execute('PRAGMA table_info("%s")' % t).fetchall()]
        deps, selfs = set(), []
        for r in src.execute('PRAGMA foreign_key_list("%s")' % t).fetchall():
            ref_table, from_col = r[2], r[3]
            if ref_table == t:
                selfs.append(from_col)          # self-reference
            else:
                deps.add(ref_table)
        fkdeps[t] = deps
        selfcols[t] = selfs
    return tables, columns, fkdeps, selfcols


def topo_order(tables, fkdeps):
    """Parent-first topological order; tolerates missing refs and cross-cycles."""
    tset = set(tables)
    ordered, seen = [], set()

    def visit(t, stack):
        if t in seen:
            return
        if t in stack:                          # cross-table cycle -> break it
            return
        stack.add(t)
        for dep in sorted(fkdeps.get(t, ())):
            if dep in tset:
                visit(dep, stack)
        stack.discard(t)
        if t not in seen:
            seen.add(t); ordered.append(t)

    for t in tables:
        visit(t, set())
    return ordered


def _ident(name):
    return '"%s"' % name.replace('"', '""')


def _sqlite_type_to_pg(decl):
    """Map a SQLite declared type to a Postgres type for reconciled columns."""
    u = (decl or "").upper()
    if "INT" in u:
        return "bigint"
    if any(k in u for k in ("CHAR", "CLOB", "TEXT")):
        return "text"
    if any(k in u for k in ("REAL", "FLOA", "DOUB", "NUMERIC", "DEC")):
        return "double precision"
    if "BLOB" in u:
        return "bytea"
    return "text"   # app stores dates/bools/misc as TEXT/INTEGER; TEXT is a safe default


def run_copy(src, dst, paramstyle, is_pg, id_tables, log=print):
    """Copy all data src -> dst. paramstyle: '%s' (pg) or '?' (sqlite self-test)."""
    tables, columns, fkdeps, selfcols = discover(src)
    order = topo_order(tables, fkdeps)
    ph = paramstyle
    copied = {}
    # Source SQLite is authoritative. Clear target tables first (children-first,
    # i.e. reverse FK order) so seeded bookkeeping rows (e.g. app_migrations,
    # created by init_db) don't collide and the copy is idempotent/re-runnable.
    cc = dst.cursor()
    if is_pg:
        # SQLite doesn't enforce FKs by default, so the source can contain orphan
        # rows; disable FK/trigger checks for a faithful bulk load. (Railway's PG
        # role is superuser; constraints still apply to future writes.)
        cc.execute("SET session_replication_role = replica")
    for t in reversed(order):
        cc.execute("DELETE FROM %s" % _ident(t))
    dst.commit()
    for t in order:
        cols = columns[t]
        rows = src.execute("SELECT %s FROM %s" % (
            ", ".join(_ident(c) for c in cols), _ident(t))).fetchall()
        copied[t] = len(rows)
        if not rows:
            log("  %-26s 0 rows" % t)
            continue
        selfs = selfcols[t]
        self_idx = [cols.index(c) for c in selfs]
        col_list = ", ".join(_ident(c) for c in cols)
        placeholders = ", ".join([ph] * len(cols))
        insert = "INSERT INTO %s (%s) VALUES (%s)" % (_ident(t), col_list, placeholders)
        # pass 1: insert, nulling any self-referential columns
        dcur = dst.cursor()
        batch = []
        for r in rows:
            vals = list(r)
            for i in self_idx:
                vals[i] = None
            batch.append(tuple(vals))
        dcur.executemany(insert, batch)
        # pass 2: restore self-referential columns
        if self_idx and "id" in cols:
            id_pos = cols.index("id")
            for c, i in zip(selfs, self_idx):
                upd = "UPDATE %s SET %s=%s WHERE %s=%s" % (
                    _ident(t), _ident(c), ph, _ident("id"), ph)
                pairs = [(r[i], r[id_pos]) for r in rows if r[i] is not None]
                if pairs:
                    dcur.executemany(upd, pairs)
        dst.commit()
        log("  %-26s %d rows%s" % (t, len(rows), "  (+self-ref pass)" if self_idx else ""))

    # reseed identity sequences (Postgres only)
    if is_pg:
        rcur = dst.cursor()
        for t in order:
            if t.lower() in id_tables and copied.get(t):
                rcur.execute(
                    "SELECT setval(pg_get_serial_sequence(%s, 'id'), "
                    "GREATEST((SELECT COALESCE(MAX(id),0) FROM %s), 1))" % (ph, _ident(t)),
                    (t,))
        dst.commit()
        log("  identity sequences reseeded")
        rcur.execute("SET session_replication_role = DEFAULT")  # re-enable FK/triggers
        dst.commit()
    return copied, order


def ensure_schema(src, dst, log=print):
    """Create the target schema from the SOURCE's own DDL (sqlite_master), so the
    target matches the source column-for-column — SQLite rewrites a table's stored
    CREATE text on ALTER ADD COLUMN, so this captures every migrated column even if
    the migration code lives outside db.init_db. Tables are created parent-first."""
    tables, columns, fkdeps, selfcols = discover(src)
    order = topo_order(tables, fkdeps)
    tddl = {r[0]: r[1] for r in src.execute(
        "SELECT name, sql FROM sqlite_master WHERE type='table' AND sql IS NOT NULL "
        "AND name NOT LIKE 'sqlite_%'").fetchall()}
    cur = dst.cursor()
    made = 0
    for t in order:
        sql = tddl.get(t)
        if not sql:
            continue
        try:
            cur.execute(db.translate_sql(sql, False)); dst.commit(); made += 1
        except Exception as e:
            dst.rollback(); log("  table %s: %s" % (t, str(e).splitlines()[0][:90]))
    idx = 0
    for name, sql in src.execute(
            "SELECT name, sql FROM sqlite_master WHERE type='index' AND sql IS NOT NULL "
            "AND name NOT LIKE 'sqlite_%'").fetchall():
        try:
            cur.execute(db.translate_sql(sql, False)); dst.commit(); idx += 1
        except Exception as e:
            dst.rollback(); log("  index %s: %s" % (name, str(e).splitlines()[0][:90]))
    # Column reconciliation: SQLite's stored CREATE text (sqlite_master.sql) can
    # lag behind the ACTUAL columns — runtime `ALTER TABLE ... ADD COLUMN` in
    # app.py (e.g. users.tour_*_done) isn't always reflected there, and a table
    # created by an earlier partial run may predate such columns. PRAGMA
    # table_info reports the real columns, so add any that the target is missing.
    reconciled = 0
    for t in order:
        info = src.execute('PRAGMA table_info(%s)' % _ident(t)).fetchall()  # (cid,name,type,...)
        have = {r[0].lower() for r in dst.execute(
            "SELECT column_name FROM information_schema.columns WHERE table_name=%s",
            (t,)).fetchall()}
        for col in info:
            cname, ctype = col[1], col[2]
            if cname.lower() in have:
                continue
            try:
                cur.execute('ALTER TABLE %s ADD COLUMN IF NOT EXISTS %s %s' % (
                    _ident(t), _ident(cname), _sqlite_type_to_pg(ctype)))
                dst.commit(); reconciled += 1
                log("  + %s.%s (%s)" % (t, cname, _sqlite_type_to_pg(ctype)))
            except Exception as e:
                dst.rollback(); log("  col %s.%s: %s" % (t, cname, str(e).splitlines()[0][:80]))
    log("  schema ensured: %d tables, %d indexes, %d columns reconciled" % (made, idx, reconciled))


def verify(src, dst, tables):
    """Row-count verification report. Returns list of (table, src_n, dst_n) mismatches."""
    print("\n=== copy verification (row counts) ===")
    mismatches = []
    total_s = total_d = 0
    for t in tables:
        s = src.execute("SELECT COUNT(*) FROM %s" % _ident(t)).fetchone()[0]
        d = dst.execute("SELECT COUNT(*) FROM %s" % _ident(t)).fetchone()[0]
        total_s += s; total_d += d
        flag = "OK " if s == d else "MISMATCH"
        if s != d:
            mismatches.append((t, s, d))
        print("  [%s] %-26s src=%-7d dst=%-7d" % (flag, t, s, d))
    print("  ----")
    print("  TOTAL rows: src=%d dst=%d" % (total_s, total_d))
    return mismatches


def main():
    url = os.environ.get("DATABASE_URL")
    if not url:
        print("ERROR: DATABASE_URL not set (target Postgres).", file=sys.stderr)
        return 2
    if not db.DB_PATH.exists():
        print("ERROR: source SQLite not found at %s" % db.DB_PATH, file=sys.stderr)
        return 2
    if "--yes" not in sys.argv:
        print("About to copy %s  ->  %s" % (db.DB_PATH, url.split("@")[-1]))
        if input("Proceed? [y/N] ").strip().lower() != "y":
            return 1

    import psycopg
    src = sqlite3.connect(str(db.DB_PATH)); src.row_factory = sqlite3.Row
    dst = psycopg.connect(url)
    try:
        if "--init" in sys.argv:
            print("=== ensuring target schema (from source DDL) ===")
            ensure_schema(src, dst)
        print("\n=== copying tables (FK-safe order) ===")
        copied, order = run_copy(src, dst, "%s", True, _id_tables())
        mism = verify(src, dst, [t for t in order if copied.get(t)])
    finally:
        src.close(); dst.close()
    if mism:
        print("\nFAILED: %d table(s) mismatch -> %s" % (len(mism), mism), file=sys.stderr)
        return 1
    print("\nSUCCESS: all tables copied, row counts match.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
